command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "3c271accc127e8ff6a4cc120d6c055d7bc97bece") { throw "main moved" }

git -C $env:GITHUB_WORKSPACE push origin --delete work/content-search
if ($LASTEXITCODE -ne 0) { throw "content search branch cleanup failed" }

Write-Host "CONTENT_SEARCH_WORK_BRANCH_DELETED"
